// Generated by AI
import { EventEmitter } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { afterEach, expect, it, vi } from 'vitest';
import { runLocalFelanHeadless } from '../src/headless.js';
import { SessionClient, type SessionClientOptions } from '../src/client/client.js';
import { identityFor } from '../../daemon/src/daemon/target.js';
import { FakeTransport, snapshot } from './client-fixtures.js';

const roots: string[] = [];
afterEach(async () => { await Promise.all(roots.splice(0).map(path => rm(path, { recursive: true, force: true }))); });

it.each(['text', 'json'] as const)('reports an elevation mismatch once in headless %s mode without stdout or relaunch', async mode => {
  const daemonRuntime = await mkdtemp(join(tmpdir(), 'elevation-headless-')); roots.push(daemonRuntime);
  const error = Object.assign(new Error('The running daemon is elevated. Stop it from an elevated terminal, then retry.'), { code: 'elevation_mismatch' });
  const connector = vi.fn(async () => { throw error; });
  const createClient = vi.fn((options: SessionClientOptions) => new SessionClient({ ...options, connector }));
  const writeOutput = vi.fn(); const writeError = vi.fn();
  expect(await runLocalFelanHeadless({ mode, daemonRuntime, initialMessage: 'hello', createClient, signalSource: new EventEmitter(), writeOutput, writeError })).toBe(1);
  expect(writeError.mock.calls).toEqual([[error.message]]); expect(writeOutput).not.toHaveBeenCalled();
  expect(createClient).toHaveBeenCalledOnce(); expect(connector).toHaveBeenCalledOnce();
});

it.each([
  ['text', './fixtures/../sessions'], ['json', './fixtures/../sessions'], ['text', undefined], ['json', undefined],
] as const)('forwards only an explicitly supplied directory on every headless attach (%s, %s)', async (mode, sessionDir) => {
  const fake = new FakeTransport();
  const createClient = (options: SessionClientOptions) => {
    const client = new SessionClient({ ...options, connector: fake.connector });
    const identity = identityFor(client.target, 'headless-fixture');
    fake.onSend = (request, connection) => {
      if (request.op === 'hello') fake.reply(request, { attachmentId: `hello-${connection}`, principal: 'principal', daemonVersion: options.expectedDaemonVersion,
        protocol: 1, identity, operations: ['attach', 'detach', 'prompt', 'session.history', 'host.status'], interactionKinds: [], capabilities: options.capabilities }, connection);
      else if (request.op === 'attach') fake.reply(request, { attachmentId: `binding-${connection}`, snapshot: snapshot() }, connection);
      else if (request.op === 'prompt') fake.reply(request, { runId: 'run' }, connection);
      else if (request.op === 'session.history') fake.reply(request, snapshot().history, connection);
      else if (request.op === 'host.status') fake.reply(request, { identity, daemonVersion: options.expectedDaemonVersion, protocol: 1, state: 'ready',
        active: { sessions: 1, runs: 0, work: 0, attachments: 1 }, setupNeeds: [] }, connection);
      else fake.reply(request, {}, connection);
    };
    return client;
  };
  const errors: string[] = [];
  const result = await runLocalFelanHeadless({ mode, sessionId: 'session', ...(sessionDir ? { sessionDir } : {}), initialMessage: 'continue', createClient,
    signalSource: new EventEmitter(), writeOutput: () => {}, writeError: error => errors.push(error) });
  expect(errors).toEqual([]);
  expect(result).toBe(0);
  const attaches = fake.requests.filter(request => request.op === 'attach');
  expect(attaches).toHaveLength(mode === 'json' ? 2 : 1);
  for (const request of attaches) {
    expect(request.session).toBe('session');
    if (sessionDir) expect(request.params).toMatchObject({ sessionDir: resolve(sessionDir) });
    else expect(request.params).not.toHaveProperty('sessionDir');
  }
  expect(fake.requests.some(request => request.op === 'sessions.create')).toBe(false);
});

it('warns about a composition-only daemon build mismatch without contaminating JSON stdout', async () => {
  const daemonRuntime = process.platform === 'win32' ? join(await mkdtemp(join(tmpdir(), 'headless-')), 'headless runtime') : '/tmp/headless runtime';
  if (process.platform === 'win32') roots.push(resolve(daemonRuntime, '..'));
  const fake = new FakeTransport();
  const daemonComposition = {
    managerPackage: '@felan-ai/felan', managerVersion: 'daemon-build', providerDigest: 'a'.repeat(64),
    configDigest: 'b'.repeat(64),
  };
  const expectedComposition = { ...daemonComposition, managerVersion: 'installed-build' };
  const createClient = (options: SessionClientOptions) => {
    const client = new SessionClient({ ...options, expectedComposition, connector: fake.connector });
    const identity = identityFor(client.target, 'headless-composition-fixture');
    fake.onSend = (request, connection) => {
      if (request.op === 'hello') fake.reply(request, { attachmentId: `hello-${connection}`, principal: 'principal', daemonVersion: options.expectedDaemonVersion,
        protocol: 1, identity, operations: ['attach', 'detach', 'prompt', 'session.history', 'host.status'], interactionKinds: [],
        capabilities: options.capabilities, composition: daemonComposition }, connection);
      else if (request.op === 'attach') fake.reply(request, { attachmentId: `binding-${connection}`, snapshot: snapshot() }, connection);
      else if (request.op === 'prompt') fake.reply(request, { runId: 'run' }, connection);
      else if (request.op === 'session.history') fake.reply(request, snapshot().history, connection);
      else if (request.op === 'host.status') fake.reply(request, { identity, daemonVersion: options.expectedDaemonVersion, protocol: 1, state: 'ready',
        composition: daemonComposition, active: { sessions: 1, runs: 0, work: 1, attachments: 1 }, setupNeeds: [] }, connection);
      else fake.reply(request, {}, connection);
    };
    return client;
  };
  const output: string[] = [];
  const errors: string[] = [];
  const result = await runLocalFelanHeadless({ mode: 'json', sessionId: 'session', initialMessage: 'continue', createClient,
    daemonRuntime, signalSource: new EventEmitter(), writeOutput: line => { output.push(line); }, writeError: error => { errors.push(error); } });

  expect(result).toBe(0);
  expect(errors).toHaveLength(1);
  expect(errors[0]).toMatch(/^Daemon .+ is running a different package\/provider build from this installation\./);
  expect(errors[0]).not.toContain('this installation expects');
  expect(errors[0]).toContain(`Run felan daemon restart --daemon-runtime '${daemonRuntime}' to apply the new build.`);
  expect(output).toEqual([]);
  expect(fake.requests.filter(request => request.op === 'prompt')).toHaveLength(1);
});
